class MobDocRegisterBarcode extends TFMDocumentHandler
{
    InventDim                           inventDim;
    InventTable                         inventTable;
    TFMInventDimSetup                   mobInventDimSetup;
    InventItemBarcode                   inventItemBarCode;
    TFMRequestItemAndDimensionElement   barcodeRequest;
    TFMPromptForUnit                    promptForUnit;
    NoYes                               promptForBarcodeSetup;
    BarcodeSetupID                      DefaultBarcodeSetup;
    NoYes                               promptForQuantity;
    NoYes                               showInfo;

}

Method.Source:
