/// <summary>
/// Method to create a "Register Barcode" configuration.
/// </summary>
protected Map createRegisterBarcodeRegistration()
{
    Map                     returnMap;
    int                     add;
    Str                     html;
    InventDimParm           parm                =  InventDimParm::activeDimFlag(InventDimGroupSetup::newInventTable(inventTable));
    boolean                 usesSerialNumber    = parm.InventSerialIdFlag;

    parm.clear();
    parm.setActiveProductDim(EcoResProductDimGroupSetup::newInventTable(inventTable));
    add += 10;
    returnMap = TFMInventDimHelper::GetInventDimCollectors(add,mobInventDimSetup,parm);
    // Information step
    if (showInfo)
    {
        html = TFMHelper::makeItemHTML(inventTable);
        returnMap.insert('info',TFMRegistrationCollectorInformation::InformationStepMap(10, 'info', inventTable.ItemId, '', html));
    }
    if (promptForBarcodeSetup)
    {
        add = returnMap.elements()*10 + 10;
        returnMap.insert(extendedTypeStr(BarcodeSetupId),TFMRegistrationCollectorList::ListStepMap(false,add,extendedTypeStr(BarcodeSetupId),"@DMF974","@DMF974",'',MobDocRegisterBarcode::getBarcodeSetup(),false,DefaultBarcodeSetup));
    }
    add+=10;
    returnMap.insert(TFMConstants::Barcode(),TFMRegistrationCollectorText::TextStepMap(false,add,TFMConstants::Barcode(),"@SYS331679","@SYS331679",'',80));
    if (usesSerialNumber)
    {
        return returnMap;
    }
    if (promptForUnit)
    {
        add+=10;
        returnMap.insert(TFMConstants::UnitOfMeasure(),TFMRegistrationCollectorList::ListStepMap(false,add,TFMConstants::UnitOfMeasure(),"@SYS40864","@SYS40864",'',TFMHelper::getConvertibleUnitList(inventTable)));
    }
    if(promptForQuantity)
    {
        add+=10;
        returnMap.insert(TFMConstants::Quantity(),TFMRegistrationCollectorDecimal::DecimalStepMap(add,TFMConstants::Quantity(),"@SYS102891","@SYS102891",'',false,'',0,10000000,14));
    }
    return returnMap;
}

/// <summary>
/// Method to post Barcode registrations.
/// </summary>
[TFMPostMethod(tableStr(InventItemBarcode)), TFMPostMethod(tableStr(InventTable))]
protected void postBarcodeRegistration()
{
    //ItemId                      itemid;
    BarcodeSetupId              barcodeSetupId;
    UnitOfMeasureSymbol         unit;
    Qty                         qty;
    int                         lineBefore;
    BarCodeString               itemBarcode;
    InventDimCombination        inventDimCombination;

    barcodeSetupId  = barcodeRequest.parmBarcodeSetupId() ? barcodeRequest.parmBarcodeSetupId() :DefaultBarcodeSetup;// requestDataNode.getNamedElement(#BarcodeSetupId).text();
    itemBarcode     = barcodeRequest.parmBarcode();//requestDataNode.getNamedElement(#Barcode).text();

    inventItemBarCode.itemId = barcodeRequest.parmitemid();

    inventItemBarCode.Description = InventTable::find(inventItemBarCode.itemId).defaultProductName();
    inventItemBarCode.UnitID = InventTable::find(inventItemBarCode.itemId).salesUnitId();
    inventItemBarCode.BarcodeSetupId = RetailInventTable::find(inventItemBarCode.itemId).BarcodeSetupId;
    inventItemBarCode.itemBarCode  = itemBarcode;

    qty = promptForQuantity ? barcodeRequest.parmQuantity() : 1;
    unit = barcodeRequest.parmUnitOfMeasure() ? barcodeRequest.parmUnitOfMeasure() :  inventTable.inventUnitId();

    inventItemBarCode.qty = qty;
    inventItemBarCode.UnitID = unit;

    inventDim = barcodeRequest.createInventDim(inventDim);

    inventItemBarCode.inventDimId = inventDim.inventDimId;
    inventItemBarCode.barcodeSetupId = barcodeSetupId;

    inventItemBarCode.useForInput = true;

    select firstonly RetailVariantId from inventDimCombination where inventDimCombination.ItemId == inventItemBarCode.itemId && inventDimCombination.InventDimId == inventDim.inventDimId;

    inventItemBarCode.RetailVariantId = inventDimCombination.RetailVariantId;

    lineBefore = Global::infologLine();
    if(inventItemBarCode.validateWrite(true))
    {
        inventItemBarCode.write();
        ResultStr = "@SYS11408";
    }
    else
    {
        ResultStr = this.extractInfoLogInfo(lineBefore,Global::infologLine());
    }
}

private str extractInfoLogInfo(int _fromLine, int _toLine)
{

    str result,temp;

    while(_fromLine <= _toLine)
    {
        temp = infolog.text(_fromLine);
        temp = strRem(temp,'\t');
        temp = strLTrim(temp);
        result +=  temp;
        if(result != '' && _fromLine != _toLine)
        {
            result += '\n';
        }
        _fromLine++;
    }
    return result;
}

public static str getBarcodeSetup()
{

    BarcodeSetup    barcodeSetup;
    str             barcodeValues;

    while select barcodeSetupId from barcodeSetup
    {

        if(barcodeValues != '')
        {
            barcodeValues += ';';
        }
        barcodeValues += barcodeSetup.barcodeSetupId;

    }
    return barcodeValues;
}

/// <summary>
/// Method to create the filter/header for the Register Barcode page.
/// </summary>
/// <returns>The Filter as an XML formatted string.</returns>
[TFMReferenceDataMethod]
public TFMReferenceDataConfiguration RegisterBarcodeHeader()
{
    TFMReferenceDataConfiguration refConf = new TFMReferenceDataConfiguration();
    // Item number text box
    refConf.addCollector(TFMGetReferenceData::defaultItemIdCollector(3));

    return refConf;
}

public boolean preProcess()
{

    // Get the dimension setup for the item
    barcodeRequest = classIdGet(request) == classNum(TFMRequestItemAndDimensionElement) ? request : null;
    inventTable = request.parmInventTable();
    mobInventDimSetup   = TFMInventDimSetup::Construct(inventTable);
    return true;
}
